import {
  BigNumbersSectionData,
  LineBarChartsSectionData,
  WaterfallSectionData,
} from '../types';

export const isOvertimePerformanceEmpty = (
  data: BigNumbersSectionData[] | undefined | null,
): boolean => {
  if (!data?.length) {
    return true;
  }

  return data.every((item) => !item?.data?.length);
};

export const isOvertimeTrendsEmpty = (
  data: LineBarChartsSectionData | undefined | null,
): boolean => {
  if (!data) {
    return true;
  }

  return !!data.empty;
};

export const isContributionEmpty = (
  data: WaterfallSectionData | undefined | null,
  variant: 'large' | 'small' = 'large',
): boolean => {
  if (!data || data.empty) {
    return true;
  }

  const chartData = data[variant];

  if (!chartData || chartData.empty) {
    return true;
  }

  return !chartData.labels?.length;
};
